# ── Fold the duplicate LP prompts into their coaching entries ─────────────
# Each Amazon Leadership Principle existed TWICE: once as a coaching entry
# ("STAR: <principle>" - what the LP means, what to show, what the probes are)
# and once as a question prompt ("Tell me about a time you X (LP: Y)" -
# carrying a ready-made worked STAR script). Complementary content, but two
# separate study units for one principle: she would work Frugality twice under
# two titles, paying prep_minutes for both.
#
# So the script becomes an extra worked example on the coaching entry, the
# question phrasing survives as a searchable alias, and the duplicate entry is
# dropped. Net: 13 fewer entries, no content lost, and the surviving entry
# reads rubric -> model answer -> probes in one place.
# Two entries that are genuinely the SAME topic under two titles, found by a
# normalised-title scan. Everything else that scan flagged - House Robber vs
# House Robber II, Path Sum I/II/III, Single Number I/II/III - are legitimate
# sequels with different algorithms, so only these two are folded. Keyed
# duplicate -> canonical (the richer entry survives).
_TITLE_DUPLICATES = {
    "How Many Numbers Are Smaller Than the Current Number":
        "How Many Numbers Are Smaller Than the Current",
    "Reverse proxy vs forward proxy":
        "Forward proxy vs reverse proxy",
    # Found by a CODE-similarity scan rather than a title scan - these four
    # pairs are the same LeetCode problem written twice under different names,
    # which a normalised-title comparison misses entirely. In each case the
    # richer entry (diagram, longer answer) survives.
    "Min Stack (O(1) getMin)": "Design a Min Stack",
    "Sqrt(x) via Binary Search": "Sqrt(x) — integer square root (binary search)",
    "Excel Sheet Column Title": "Number to Excel Column Title",
    "Count Negative Numbers in a Sorted Matrix": "Count Negatives in a Sorted Matrix",
}
# NOT folded, deliberately: the scan also flags the bank's PATTERN entries
# against their exemplar problems - "Dynamic Programming - the 4-question
# method" vs Coin Change, "Sliding Window - recognize & apply" vs Longest
# Substring Without Repeating Characters, "Graphs - BFS, DFS" vs Number of
# Islands, "Heap / Top-K" vs Kth Largest, "Binary Search Lower Bound" vs Search
# Insert Position. Those share code ON PURPOSE: one teaches the pattern, the
# other drills it. Folding them would delete the teaching layer.

